def create_patch_with_signature(signature: float) -> torch.Tensor:
    """Create a patch tensor [N_POINTS, 3] filled with a unique signature value."""
    return torch.full((N_POINTS, 3), signature, dtype=torch.float32)


def create_tuple(num_patches: int, start_signature: int) -> dict:
    """Create a single tuple dict with num_patches patches (all positive).

    Args:
        num_patches: number of patches in this tuple (M_i)
        start_signature: the signature value for the first patch in this tuple

    Returns:
        A tuple dict with 'patches', 'num_positive_patches', 'num_negative_patches'
    """
    patches = torch.stack([
        create_patch_with_signature(float(start_signature + i))
        for i in range(num_patches)
    ], dim=0)  # Shape: [num_patches, N_POINTS, 3]

    return {
        "patches": patches,
        "num_positive_patches": num_patches,
        "num_negative_patches": 0
    }


def create_tuple_with_negative(num_positive: int, start_signature: int, negative_signature: float) -> dict:
    """Create a single tuple dict with positive patches and one negative patch.

    Args:
        num_positive: number of positive patches in this tuple (M_i)
        start_signature: the signature value for the first positive patch
        negative_signature: the signature value for the negative patch (use negative values)

    Returns:
        A tuple dict with 'patches', 'num_positive_patches', 'num_negative_patches'
    """
    positive_patches = [
        create_patch_with_signature(float(start_signature + i))
        for i in range(num_positive)
    ]
    negative_patch = create_patch_with_signature(negative_signature)

    all_patches = torch.stack(positive_patches + [negative_patch], dim=0)

    return {
        "patches": all_patches,
        "num_positive_patches": num_positive,
        "num_negative_patches": 1
    }


