def create_batch(tuple_sizes: List[int]) -> List[dict]:
    """Create a batch of all-positive tuples with specified sizes.

    Args:
        tuple_sizes: list of M_i values, e.g., [3, 2, 2]

    Returns:
        List of tuple dicts forming a batch
    """
    batch = []
    start_signature = 0
    for size in tuple_sizes:
        batch.append(create_tuple(size, start_signature))
        start_signature += size
    return batch


def create_batch_with_negatives(
        tuple_sizes: List[int],
        signature_offset: int = 0,
        neg_signature_start: float = -1.0
) -> List[dict]:
    """Create a batch of tuples with positives and one negative each.

    Args:
        tuple_sizes: list of M_i values (positive counts), e.g., [3, 2, 2]
        signature_offset: starting signature for positive patches (to distinguish from other batches)
        neg_signature_start: starting signature for negative patches

    Returns:
        List of tuple dicts, each with M_i positives and 1 negative
    """
