    start_signature = signature_offset
    negative_signature = neg_signature_start

    for size in tuple_sizes:
        batch.append(create_tuple_with_negative(size, start_signature, negative_signature))
        start_signature += size + 1  # +1 for the negative patch
        negative_signature -= 1.0

    return batch


